ssh bjb1-18228 "source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && cd /root/acr-vla-conformal-refinement && echo '=== PROCESS ===' && ps -p 356495 -o pid,etime,cmd 2>/dev/null || echo 'PROCESS NOT FOUND' && echo '=== LOGS ===' && ls -lt logs/*obs*only*seed43* 2>/dev/null || echo 'NO LOG FILES' && echo '=== TMUX ===' && ls -lt /tmp/tmux_eval* 2>/dev/null | head -5 || echo 'NO TMUX LOGS' && echo '=== JSON PROGRESS ===' && python3 -c \"
import json, glob, os
files = glob.glob('logs/eval_object*obs*only*seed43*.json') + glob.glob('logs/eval_object*obs_only*seed43*.json') + glob.glob('logs/*obs*only*object*seed43*.json')
files = list(set(files))
if not files:
    print('NO JSON FILES FOUND')
    # try broader search
    import subprocess
    r = subprocess.run(['find', 'logs/', '-name', '*obs*only*seed43*'], capture_output=True, text=True)
    print('find result:', r.stdout)
else:
    for f in sorted(files):
        try:
            data = json.load(open(f))
            tasks = data.get('tasks', data.get('results', data.get('task_results', [])))
            if isinstance(tasks, list):
                print(f'{f}: {len(tasks)} tasks completed')
                for t in tasks:
                    name = t.get('task_name', t.get('name', '?'))
                    sr = t.get('success_rate', t.get('sr', '?'))
                    print(f'  {name}: SR={sr}')
            elif isinstance(tasks, dict):
                print(f'{f}: {len(tasks)} tasks completed')
                for k, v in tasks.items():
                    print(f'  {k}: {v}')
            else:
                print(f'{f}: unexpected format, keys={list(data.keys())}')
            # check for overall SR
            overall = data.get('overall_sr', data.get('mean_sr', data.get('average_success_rate', None)))
            if overall is not None:
                print(f'  OVERALL SR: {overall}')
        except Exception as e:
            print(f'{f}: error {e}')
